int partition(Elem A[], int p, int q, Elem x) {
  int i = p;
  for (int j = p + 1; j <= q; ++j) {
      if (A[j] <= x) {
          ++i;
          swap(A[i], A[j]);
      }
  }
  swap(A[p], A[i]);
  return i;
}

